func:
let blocks = msg.payload;

// Guard clause to ensure all network blocks arrived safely
if (!blocks.vbr_status_block || !blocks.power_temp_block ||
    !blocks.control_metrics_block || !blocks.vib_extended_block) return null;

// ---------------------------------------------------------------
// HELPER: Modbus registers arrive as UNSIGNED 16-bit (0..65535).
// Sensor values that can legitimately be negative (acceleration,
// chip temperature below 0 degC) are 16-bit SIGNED and must be
// re-interpreted, or -0.5g would read as +65535-ish garbage.
// ---------------------------------------------------------------
function toSigned16(v) {
    return v > 32767 ? v - 65536 : v;
}

function safe(v) {
    return (typeof v === "number" && isFinite(v)) ? v : 0;
}

// 1. D210 Motor Status (block now contains only this single register)
let statusCode = blocks.vbr_status_block[0];

// 2. D222 Range parsing (Indices relative to start address 222)
let voltage = blocks.power_temp_block[0];
let amp = blocks.power_temp_block[1] / 100;
let power = blocks.power_temp_block[2] / 10;
let torque = blocks.power_temp_block[3] / 10;
let temperature = blocks.power_temp_block[8];

// 3. D4110 High-Range parsing (Parsing REALs/Floats from registers)
function parse32BitFloatSwapped(reg1, reg2) {
    let buffer = new ArrayBuffer(4);
    let view = new DataView(buffer);
    view.setUint16(0, reg2, false);
    view.setUint16(2, reg1, false);
    let result = view.getFloat32(0, false);
    return isNaN(result) ? 0 : result;
}

let frequency = parse32BitFloatSwapped(blocks.control_metrics_block[0], blocks.control_metrics_block[1]);
let rpm = parse32BitFloatSwapped(blocks.control_metrics_block[2], blocks.control_metrics_block[3]);

// 4. Calculate Speed Command and apply industrial state safety override
let speed_hz = blocks.control_metrics_block[102] / 200; // D4212 raw mapping

// CRITICAL FIX: If motor is E-STOP (0) or STOPPED (1), force target speed command to 0 Hz
if (statusCode === 0 || statusCode === 1) {
    speed_hz = 0;
}

// ---------------------------------------------------------------
// 5. D400 Range: EXTENDED VIBRATION BLOCK (new)
//    PLC COM0 reads ONE 19-register block: sensor addr 52 (0x34)
//    through 70 (0x46) -> D400..D418. Offsets below are relative
//    to D400 = index 0 = sensor register 0x34. Reserved gaps are
//    read but discarded (0x37-0x39, 0x3D-0x3F).
//
//    KNOWN LIMITATION (confirmed by controlled substitution test):
//    AX/AY/AZ (offsets 0-2) read back as hard 0x0000 on this sensor
//    unit regardless of PLC row/mapping. Velocity/temp/displacement/
//    frequency in the SAME transaction are all valid, so the
//    accelerometer itself is working (velocity is derived from it) -
//    this looks like a firmware limitation on the raw-acceleration
//    passthrough register specifically, not a dead sensor. Kept in
//    the payload (as 0) rather than removed, so it's visible in
//    Grafana as "not yet resolved" rather than silently missing.
// ---------------------------------------------------------------
let vibExt = blocks.vib_extended_block;

// Vibration velocity, now sourced HERE (offsets 6-8 = D406-408 =
// sensor reg 0x3A-0x3C = VX,VY,VZ), matching the PLC variable table's
// Motor_VBR_VX/VY/VZ. Same scaling as before: raw / 100 -> mm/s.
let vbr_x = vibExt[6] / 100;
let vbr_y = vibExt[7] / 100;
let vbr_z = vibExt[8] / 100;

// Acceleration: A = signed_raw / 32768 * 16   [g]   (offsets 0-2)
// Signed, because a real accelerometer swings both directions.
let accel_x = toSigned16(vibExt[0]) / 32768 * 16;
let accel_y = toSigned16(vibExt[1]) / 32768 * 16;
let accel_z = toSigned16(vibExt[2]) / 32768 * 16;

// offsets 3-5 = reserved (0x37-0x39), discarded
// offsets 6-8 = VX,VY,VZ (0x3A-0x3C) - duplicate of D200-202, not used here
// offsets 9-11 = reserved (0x3D-0x3F), discarded

// Sensor's own chip temperature = signed_raw / 100   [degC]  (offset 12)
// NB: this is the SENSOR chip, NOT the motor. Motor temp is `temperature`
// above (D230). Named distinctly on purpose so the two never get confused.
let sensor_chip_temp = toSigned16(vibExt[12]) / 100;

// Vibration displacement: raw value is already in micrometres [um]  (13-15)
let disp_x = vibExt[13];
let disp_y = vibExt[14];
let disp_z = vibExt[15];

// Dominant vibration frequency = raw / 10   [Hz]  (offsets 16-18)
let vib_freq_x = vibExt[16] / 10;
let vib_freq_y = vibExt[17] / 10;
let vib_freq_z = vibExt[18] / 10;

// 6. Map Operational State Text Labels
let statusLabel = "UNKNOWN";
switch (statusCode) {
    case 0: statusLabel = "E-STOP"; break;
    case 1: statusLabel = "STOPPED"; break;
    case 2: statusLabel = "RUNNING"; break;
}

// 7. Build Shared Identity Metadata
let identityTags = { asset_id: "motor_01" };

// ==========================================
// OUTPUT MESSAGE 1: Tailored for InfluxDB Out
// ==========================================
let msgInflux = {
    payload: {
        vibration_x: safe(vbr_x),
        vibration_y: safe(vbr_y),
        vibration_z: safe(vbr_z),
        temperature: safe(temperature),
        current: safe(amp),
        torque: safe(torque),
        speed_command_hz: safe(speed_hz), // Safely drops to 0 on stop
        frequency: frequency,
        rpm: rpm,
        voltage: safe(voltage),
        power: safe(power),
        status_code: statusCode,

        // --- new extended vibration fields ---
        accel_x: safe(accel_x),
        accel_y: safe(accel_y),
        accel_z: safe(accel_z),
        sensor_chip_temp: safe(sensor_chip_temp),
        disp_x: safe(disp_x),
        disp_y: safe(disp_y),
        disp_z: safe(disp_z),
        vib_freq_x: safe(vib_freq_x),
        vib_freq_y: safe(vib_freq_y),
        vib_freq_z: safe(vib_freq_z)
    },
    tags: identityTags
};

// Clean out measurement property properties to keep Grafana rows clear
delete msgInflux.measurement;

// ==========================================
// OUTPUT MESSAGE 2: Tailored for Postgres Pipeline
// ==========================================
let msgPostgres = {
    payload: {
        status_code: statusCode,
        status_label: statusLabel
    },
    tags: identityTags
};

return [msgInflux, msgPostgres];

let statusData = msg.payload;
let tagsData = msg.tags;

// Assign the raw SQL string statement directly to msg.query
msg.query = `INSERT INTO machine_activity_logs (asset_id, status_code, status_label) 
             VALUES ('${tagsData.asset_id}', ${statusData.status_code}, '${statusData.status_label}');`;

return msg;
